int aa_setprocattr(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0) {
        return -EINVAL;
    }

    if (current != task) {
        return -EPERM;
    }

    if (!value || !((char *)value)[0]) {
        return -EINVAL;
    }

    if (strcmp(name, "current") == 0) {
        int ret = aa_change_profile(task, value);
        if (ret < 0) {
            audit_log_current(LOG_CONTEXT, AUDIT_AA_SETATTR_FAILURE,
                              "aa_setprocattr", name, value, size, ret);
            return ret;
        }
        return (int)size;
    } else if (strcmp(name, "permissions") == 0) {
        int ret = aa_update_permissions(task, value);
