int apparmor_setprocattr(struct task_struct *task, char *name, void *value, size_t size)
{
    if (size == 0 || task != current)
        return -EINVAL;

    if (!value)
        return -EFAULT;

    if (name == NULL)
        return -EINVAL;

    if (strcmp(name, "current") == 0) {
        int ret = -EINVAL;
        char *cmd = value;

        if (strncmp(cmd, "hat", 3) == 0) {
            if (cmd[3] == '\0') {
                ret = 0;
            } else if (cmd[3] == '/') {
                ret = apparmor_change_hat(cmd + 4);
            }
        } else if (strncmp(cmd, "change_hat", 9) == 0) {
            if (cmd[9] == '/' && cmd[10] != '\0') {
                ret = apparmor_change_hat(cmd + 10);
            }
        } else if (strncmp(cmd, "exec", 4) == 0) {
            ret = apparmor_change_profile();
        }

        if (ret >= 0)
            return size;
    }

    audit_log(current->audit_context, AUDIT_AA_SETATTR_FAIL,
              "apparmor_setprocattr failed", name, value, size);
    return -EACCES;
}

