int aa_setprocattr(struct task_struct *task, char *name, void *value, size_t size) {
    if (!size || task != current) {
        return -EINVAL;
    }

    if (!value || strlen(name) == 0) {
        return -EINVAL;
    }

    char *str_value = value;
    if (str_value[size - 1] != '\0') {
        return -EINVAL;
    }

    if (strcmp(name, "change_profile") == 0) {
        int ret = aa_change_profile(task, str_value);
        if (ret < 0) {
            return ret;
        }
    } else if (strcmp(name, "change_perms") == 0) {
        int ret = aa_change_perms(task, str_value);
        if (ret < 0) {
            return ret;
        }
    } else {
        return -EINVAL;
    }

    return size;
}
